package uk.nktnet.webviewkiosk.config.mqtt

import kotlinx.serialization.descriptors.SerialDescriptor
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonPrimitive
import uk.nktnet.webviewkiosk.config.remote.inbound.InboundCommandMessage
import uk.nktnet.webviewkiosk.config.remote.inbound.InboundRequestMessage

/** Per-instance scripts to merge into Home Assistant's scripts.yaml. */
object HomeAssistantScripts {
    fun create(discovery: HomeAssistantDiscovery, deviceName: String): String {
        // Instance IDs generated by SystemSettings contain only these characters.
        // Keep the complete ID so two kiosks never share a script ID.
        require(discovery.appInstanceId.matches(Regex("[a-z0-9-]+")))
        val id = discovery.appInstanceId.replace('-', '_')
        val name = deviceName.ifBlank { "Webview Kiosk ${discovery.appInstanceId}" }
        val commands = variants(InboundCommandMessage.serializer().descriptor)
        val requests = variants(InboundRequestMessage.serializer().descriptor)
        val operations =
            listOf(
                Operation(
                    "command",
                    "Send command",
                    discovery.commandTopic,
                    "wk_payload.get('command') in ${jsonArray(commands)} and " +
                        "wk_payload.get('data', {}) is mapping",
                    "Provide an object with a supported command and optional data object.",
                    "{\"command\":\"notify\",\"data\":{\"contentTitle\":\"Door\",\"contentText\":\"Visitor\"},\"wakeScreen\":true}",
                ),
                Operation(
                    "settings",
                    "Update settings",
                    discovery.settingsCommandTopic,
                    "wk_payload.get('data') is mapping and " +
                        "wk_payload['data'].get('settings') is mapping",
                    "Provide an object containing data.settings as an object.",
                    "{\"showToast\":false,\"data\":{\"settings\":{\"appearance.theme\":\"DARK\"}}}",
                ),
                Operation(
                    "request",
                    "Request data",
                    discovery.requestTopic,
                    "wk_payload.get('requestType') in ${jsonArray(requests)} and " +
                        "wk_payload.get('data', {}) is mapping",
                    "Provide an object with a supported requestType and optional data object.",
                    "{\"requestType\":\"get_settings\",\"data\":{\"settings\":[\"device.brightness\",\"appearance.theme\"]}}",
                ),
            )
        return buildString {
            appendLine(
                "# Merge these three entries into scripts.yaml, then reload scripts."
            )
            appendLine(
                "# Requires this kiosk's MQTT and Home Assistant discovery to be enabled."
            )
            appendLine(
                "# Completion means MQTT publication, not confirmation from Android."
            )
            operations.forEach { operation ->
                appendLine()
                appendLine("webview_kiosk_${id}_${operation.key}:")
                appendLine("  alias: ${quote("$name: ${operation.name}")}")
                appendLine(
                    "  description: ${quote("${operation.name} over MQTT. Completion confirms publication only. Request results appear in the kiosk's result sensors.")}"
                )
                appendLine("  icon: mdi:code-json")
                appendLine("  mode: queued")
                appendLine("  max: 10")
                appendLine("  fields:")
                appendLine("    payload:")
                appendLine("      name: Payload")
                appendLine(
                    "      description: Full JSON or YAML envelope. This kiosk is targeted automatically."
                )
                appendLine("      required: true")
                appendLine("      example: ${quote(operation.example)}")
                appendLine("      selector:")
                appendLine("        object: {}")
                appendLine("  sequence:")
                // Set the local variable inside the sequence so call arguments
                // cannot override the validated payload.
                appendLine("    - variables:")
                appendLine("        wk_payload: >-")
                appendLine(
                    "          {{ payload | from_json if payload is string else payload | default(none) }}"
                )
                appendLine("    - if: >-")
                appendLine(
                    "        {{ not (wk_payload is mapping and ${operation.validation}) }}"
                )
                appendLine("      then:")
                appendLine("        - stop: ${quote(operation.error)}")
                appendLine("          error: true")
                appendLine("    - action: mqtt.publish")
                appendLine("      data:")
                appendLine("        topic: ${quote(operation.topic)}")
                appendLine("        qos: 1")
                appendLine("        retain: false")
                appendLine("        payload: >-")
                // The target is a constant, not an overridable script variable.
                appendLine(
                    "          {{ dict(wk_payload, targetInstances=[${quote(discovery.appInstanceId)}]) | to_json }}"
                )
            }
        }
    }

    private data class Operation(
        val key: String,
        val name: String,
        val topic: String,
        val validation: String,
        val error: String,
        val example: String,
    )

    private fun variants(descriptor: SerialDescriptor): Set<String> {
        val types = descriptor.getElementDescriptor(1)
        return (0 until types.elementsCount)
            .map { types.getElementDescriptor(it).serialName }
            .toSet() - "error"
    }

    private fun jsonArray(values: Set<String>) =
        JsonArray(values.sorted().map(::JsonPrimitive)).toString()

    private fun quote(value: String) = JsonPrimitive(value).toString()
}
